"""Launcher adapter for the fixed-ratio inelastic-DM production benchmark.

Input masses are mediator masses. The propagated mother is chi-prime; its
mass and lifetime never get confused with those of the prompt mediator.
"""
import numpy as np


class InelasticLLP:
    LLP_name = "Inelastic-DM"
    production_profile = "calibrated"
    decayChannels = np.array(["chi + SM"])
    # Inclusive current channel: generated by exHad, not the generic PDG sampler.
    PDGs = np.array([[4900101, 11, -11]])
    BrRatios_distr = np.array([1.])
    Matrix_elements = None
    MixingPatternArray = None
    scalar_lifetime = None
    alp_production_mode = None
    coupling_metadata = None
    xi = None
    interference = None
    uncertainty = "central"

    def __init__(self, config):
        from model_sensitivity import configure_exhad
        configure_exhad(getattr(config, "exhad_root", None))
        from exhad import inelastic_dark_matter as current
        self.current = current
        self.delta = float(getattr(config, "idm_delta", .1))
        self.dp_production_mode = config.dp_production_mode or "combined"
        self.particle_path = config.particle_selection["particle_path"]
        self.LLP_pdg = getattr(config, "llp_pdg", None) or 4900102
        self.uncertainty_label = f"{self.dp_production_mode}-delta{self.delta:g}"
        self.m_min_tabulated = np.nextafter(6*current.ME/self.delta, np.inf)
        self.m_max_tabulated = np.nextafter(3*current.MAX_CURRENT_MASS/self.delta, 0.)
        self.mass = None
        self.mediator_mass = None
        self.Yield = None  # Filled from the full source, never a guessed table.

    def set_mass(self, mediator_mass):
        self.mediator_mass = float(mediator_mass)
        self.mass = self.mediator_mass*(1+self.delta)/3

    def get_ctau(self, mediator_mass):
        return self.current.ctau(float(mediator_mass), delta=self.delta)

    def get_Br(self, mediator_mass):
        self.get_ctau(mediator_mass)  # Validate the physical decay range.
        return np.array([1.])

    def compute_mass_dependent_properties(self):
        self.c_tau_int = self.get_ctau(self.mediator_mass)

    def set_c_tau(self, value):
        self.c_tau_input = float(value)

    def decay(self, count, seed):
        return self.current.generate(self.mediator_mass, count, delta=self.delta, seed=seed)
